def weighted_aggregate(pairs):
    # pairs: [(答案数值, 置信度), ...]
    total_w = sum(w for _, w in pairs)
    if total_w == 0:
        return None
    return sum(v * w for v, w in pairs) / total_w

if __name__ == "__main__":
